from typing import Literal, TypedDict
from langchain_core.messages import AIMessage
from langgraph.graph import END, MessagesState

class UpdateMemory(TypedDict):
    """ Decision on what memory type to update """
    update_type: Literal['user', 'todo', 'instructions']

def route_message(state: MessagesState) -> Literal[END, "update_todos", "update_instructions", "update_profile"]:
    """Reflect on the memories and chat history to decide whether to update the memory collection."""
    message = state['messages'][-1]
    if len(message.tool_calls) == 0:
        return END
    else:
        tool_call = message.tool_calls[0]
        if tool_call['args']['update_type'] == "user":
            return "update_profile"
        elif tool_call['args']['update_type'] == "todo":
            return "update_todos"
        elif tool_call['args']['update_type'] == "instructions":
            return "update_instructions"
        else:
            raise ValueError

def ai(update_type=None):
    calls = [] if update_type is None else [{"name": "UpdateMemory", "args": {"update_type": update_type}, "id": "c1"}]
    return {"messages": [AIMessage(content="", tool_calls=calls)]}

for t in [None, "user", "todo", "instructions"]:
    print(t, "->", route_message(ai(t)))
try:
    route_message(ai("calendar"))
except ValueError:
